  "openrouter.ai": ["google/gemma-2-9b-it", "qwen/qwen-2.5-7b-instruct", "meta-llama/llama-3.2-3b-instruct", "meta-llama/llama-3.3-70b-instruct", "deepseek/deepseek-r1", "openai/text-embedding-3-small"],
