};
const DELAY = { "openrouter.ai": 900, "api.together.xyz": 1400, "api.fireworks.ai": 350, "api.deepinfra.com": 700 };
const calls = [];
const frontierFetch = async (url, opts = {}) => {
  const u = new URL(url);
  const auth = String(opts.headers?.authorization || "");
  if (!LISTS[u.host]) return { ok: false, status: 404, json: async () => ({}), text: async () => "unknown host" };
